CREATE TABLE IF NOT EXISTS availability (
    id text NOT NULL,
    hotel_id text NOT NULL,
    date date NOT NULL,
    room_type text NOT NULL,
    room_type_id text,
    alloted integer DEFAULT 0 NOT NULL,
    reserved integer DEFAULT 0 NOT NULL,
    available integer DEFAULT 0 NOT NULL,
    oversell integer DEFAULT 0 NOT NULL,
    waitlist integer DEFAULT 0 NOT NULL,
    no_of_rooms integer DEFAULT 0 NOT NULL,
    inserted_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS availability_assertion_balances (
    hotel_id character varying(20) NOT NULL,
    room_type character varying(20) NOT NULL,
    stay_date date NOT NULL,
    asserted_quantity integer DEFAULT 0 NOT NULL,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT availability_assertion_balances_nonnegative_ck CHECK ((asserted_quantity >= 0))
);

CREATE TABLE IF NOT EXISTS availability_assertion_movements (
    movement_id uuid NOT NULL,
    assertion_id uuid NOT NULL,
    hotel_id character varying(20) NOT NULL,
    room_type character varying(20) NOT NULL,
    stay_date date NOT NULL,
    quantity_delta integer NOT NULL,
    movement_type character varying(20) NOT NULL,
    source character varying(50),
    reference_type character varying(50),
    reference_id character varying(200),
    actor_id character varying(100),
    correlation_id character varying(100),
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    operation_id uuid,
    CONSTRAINT availability_assertion_movements_nonzero_delta_ck CHECK ((quantity_delta <> 0)),
    CONSTRAINT availability_assertion_movements_type_delta_ck CHECK (((((movement_type)::text = 'ASSERTION'::text) AND (quantity_delta > 0)) OR (((movement_type)::text = 'REVERSAL'::text) AND (quantity_delta < 0))))
);

CREATE TABLE IF NOT EXISTS availability_assertions (
    id uuid NOT NULL,
    hotel_id character varying(20) NOT NULL,
    idempotency_key character varying(200) NOT NULL,
    request_hash character varying(64) NOT NULL,
    room_type character varying(20) NOT NULL,
    arrival_date date NOT NULL,
    departure_date date NOT NULL,
    quantity integer NOT NULL,
    channel_code character varying(100),
    rate_code character varying(100),
    status character varying(20) DEFAULT 'ACTIVE'::character varying NOT NULL,
    result jsonb NOT NULL,
    source character varying(50),
    reference_type character varying(50),
    reference_id character varying(200),
    actor_id character varying(100),
    correlation_id character varying(100),
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    supersedes_assertion_id uuid,
    CONSTRAINT availability_assertions_status_ck CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'PARTIALLY_RELEASED'::character varying, 'REPLACEMENT_PENDING'::character varying, 'SUPERSEDED'::character varying, 'REJECTED'::character varying, 'RELEASED'::character varying])::text[]))),
    CONSTRAINT availability_assertions_valid_dates_ck CHECK ((arrival_date < departure_date)),
    CONSTRAINT availability_assertions_valid_quantity_ck CHECK ((quantity > 0))
);

