    CONSTRAINT billing_rules_rule_type_check CHECK ((rule_type = ANY (ARRAY['GUEST'::text, 'COMPANY'::text, 'AGENT'::text, 'CONTRACT'::text, 'PACKAGE'::text, 'ALL_INCLUSIVE'::text])))
);

