CREATE TABLE IF NOT EXISTS charge_routing (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    hotel_id text NOT NULL,
    route_code text NOT NULL,
    route_name text NOT NULL,
    route_type text NOT NULL,
    source_type text NOT NULL,
    source_id text,
    destination_type text NOT NULL,
    destination_id text,
    priority integer DEFAULT 1,
    is_default boolean DEFAULT false,
    active boolean DEFAULT true,
    created_by text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    notes text,
    CONSTRAINT charge_routing_destination_type_check CHECK ((destination_type = ANY (ARRAY['GUEST'::text, 'COMPANY'::text, 'AGENT'::text, 'AR_ACCOUNT'::text]))),
    CONSTRAINT charge_routing_route_type_check CHECK ((route_type = ANY (ARRAY['GUEST'::text, 'COMPANY'::text, 'AGENT'::text, 'CONTRACT'::text, 'COMMISSION'::text]))),
    CONSTRAINT charge_routing_source_type_check CHECK ((source_type = ANY (ARRAY['RESERVATION'::text, 'FOLIO'::text, 'ROOM_TYPE'::text, 'PACKAGE'::text])))
);

