    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TABLE IF NOT EXISTS commission_calculations (
    id text NOT NULL,
    hotel_id text NOT NULL,
    agent_id text NOT NULL,
    reservation_id text NOT NULL,
    confirmation_no text NOT NULL,
    stay_date date NOT NULL,
    room_revenue numeric(15,2) NOT NULL,
    total_revenue numeric(15,2) NOT NULL,
    commission_rate numeric(5,2) NOT NULL,
    commission_amount numeric(15,2) NOT NULL,
    calculated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    status text DEFAULT 'ACCRUED'::text,
    commission_basis text DEFAULT 'GROSS'::text,
    commissionable_amount numeric DEFAULT 0,
    CONSTRAINT commission_calculations_basis_check CHECK ((commission_basis = ANY (ARRAY['GROSS'::text, 'NET'::text, 'ROOM_REVENUE'::text, 'TOTAL_REVENUE'::text]))),
    CONSTRAINT commission_calculations_status_check CHECK ((status = ANY (ARRAY['ACCRUED'::text, 'APPROVED'::text, 'PAYABLE'::text, 'PAID'::text, 'VOIDED'::text])))
);

