CREATE TABLE IF NOT EXISTS company_accounts (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    hotel_id text NOT NULL,
    company_id text NOT NULL,
    account_code text NOT NULL,
    account_name text NOT NULL,
    account_type text NOT NULL,
    currency text DEFAULT 'USD'::text,
    current_balance numeric DEFAULT 0,
    credit_limit numeric,
    payment_terms text,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    created_by text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    notes text,
    CONSTRAINT company_accounts_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'FROZEN'::text, 'CLOSED'::text]))),
    CONSTRAINT company_accounts_type_check CHECK ((account_type = ANY (ARRAY['RECEIVABLE'::text, 'PAYABLE'::text, 'PREPAID'::text])))
);

CREATE TABLE IF NOT EXISTS company_billing (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    hotel_id text NOT NULL,
    company_id text NOT NULL,
    billing_code text NOT NULL,
    billing_date date NOT NULL,
    period_from date NOT NULL,
    period_to date NOT NULL,
    subtotal numeric DEFAULT 0,
    tax_amount numeric DEFAULT 0,
    total_amount numeric DEFAULT 0,
    paid_amount numeric DEFAULT 0,
    balance_due numeric DEFAULT 0,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    generated_by text,
    generated_at timestamp with time zone,
    due_date date,
    paid_at timestamp with time zone,
    created_by text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    notes text,
    CONSTRAINT company_billing_date_check CHECK ((period_to >= period_from)),
    CONSTRAINT company_billing_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'GENERATED'::text, 'SENT'::text, 'PAID'::text, 'VOIDED'::text])))
);

CREATE TABLE IF NOT EXISTS company_contracts (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    hotel_id text NOT NULL,
    company_id text NOT NULL,
    contract_code text NOT NULL,
    contract_name text NOT NULL,
    contract_type text NOT NULL,
    effective_from date NOT NULL,
    effective_to date NOT NULL,
    discount_type text,
    discount_value numeric,
    min_rooms integer,
    max_rooms integer,
    min_nights integer,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    approved_by text,
    approved_at timestamp with time zone,
    created_by text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    notes text,
    version integer DEFAULT 1,
    parent_contract_id text,
    is_latest boolean DEFAULT true,
    superseded_at timestamp with time zone,
    CONSTRAINT company_contracts_date_check CHECK ((effective_to >= effective_from)),
    CONSTRAINT company_contracts_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'EXPIRED'::text, 'TERMINATED'::text]))),
    CONSTRAINT company_contracts_type_check CHECK ((contract_type = ANY (ARRAY['MASTER'::text, 'SUB'::text, 'DISCOUNT'::text, 'VOLUME'::text])))
);

