CREATE TABLE IF NOT EXISTS reservation_availability_operations (
    id uuid NOT NULL,
    hotel_id character varying(20) NOT NULL,
    reservation_id text NOT NULL,
    operation_key character varying(200) NOT NULL,
    operation_type character varying(50) NOT NULL,
    request_hash character varying(64) NOT NULL,
    status character varying(20) DEFAULT 'IN_PROGRESS'::character varying NOT NULL,
    result jsonb,
    old_assertion_id uuid,
    new_assertion_id uuid,
    actor_id character varying(100),
    correlation_id character varying(100),
    causation_id character varying(100),
    failure_code character varying(100),
    failure_message text,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    completed_at timestamp(6) with time zone,
    CONSTRAINT reservation_availability_operations_status_ck CHECK (((status)::text = ANY ((ARRAY['IN_PROGRESS'::character varying, 'SUCCEEDED'::character varying, 'REJECTED'::character varying, 'FAILED'::character varying])::text[])))
);

CREATE TABLE IF NOT EXISTS reservation_availability_state (
    hotel_id character varying(20) NOT NULL,
    reservation_id text NOT NULL,
    population character varying(30) NOT NULL,
    current_assertion_id uuid,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT reservation_availability_state_legacy_link_ck CHECK ((((population)::text <> 'LEGACY'::text) OR (current_assertion_id IS NULL))),
    CONSTRAINT reservation_availability_state_population_ck CHECK (((population)::text = ANY ((ARRAY['LEGACY'::character varying, 'ASSERTION_MANAGED'::character varying])::text[])))
);

