    resv_name_id integer,
    original_room_type character varying(20) NOT NULL,
    upgraded_room_type character varying(20) NOT NULL,
    hotel_id character varying(20) NOT NULL,
    upgrade_reason character varying(200),
    approved_by integer,
    created_at timestamp(6) without time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE SEQUENCE IF NOT EXISTS room_upgrades_upgrade_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE room_upgrades_upgrade_id_seq OWNED BY room_upgrades.upgrade_id;

CREATE TABLE IF NOT EXISTS rooms (
    id text NOT NULL,
    hotel_id text NOT NULL,
    room_number text NOT NULL,
    room_type text NOT NULL,
    room_status text DEFAULT 'AVAILABLE'::text NOT NULL,
    front_office_status text DEFAULT 'CLEAN'::text NOT NULL,
    housekeeping_status text DEFAULT 'READY'::text NOT NULL,
    floor text NOT NULL,
    building text,
    beds integer DEFAULT 1 NOT NULL,
    max_occupancy integer DEFAULT 2 NOT NULL,
    max_adults integer DEFAULT 2 NOT NULL,
    max_children integer DEFAULT 1 NOT NULL,
    twin_beds integer DEFAULT 0 NOT NULL,
    queen_beds integer DEFAULT 0 NOT NULL,
    king_beds integer DEFAULT 0 NOT NULL,
    smoking boolean DEFAULT false NOT NULL,
    created_by text,
    created_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    bed_type character varying(20)
);

CREATE TABLE IF NOT EXISTS routing_instructions (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    hotel_id character varying(20) NOT NULL,
    reservation_id text NOT NULL,
    target_window_no integer DEFAULT 1 NOT NULL,
    rule_type character varying(20) NOT NULL,
    match_values jsonb DEFAULT '[]'::jsonb NOT NULL,
    apply_to character varying(15) DEFAULT 'ALL'::character varying NOT NULL,
    per_day boolean DEFAULT false NOT NULL,
    per_day_from integer,
    active boolean DEFAULT true NOT NULL,
    created_by text,
    created_at timestamp(6) with time zone DEFAULT now() NOT NULL,
    updated_at timestamp(6) with time zone DEFAULT now() NOT NULL
);

