CREATE TABLE IF NOT EXISTS travel_agent_accounts (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    hotel_id text NOT NULL,
    agent_id text NOT NULL,
    account_code text NOT NULL,
    account_name text NOT NULL,
    account_type text NOT NULL,
    currency text DEFAULT 'USD'::text,
    current_balance numeric DEFAULT 0,
    credit_limit numeric,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    created_by text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    notes text,
    CONSTRAINT travel_agent_accounts_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'FROZEN'::text, 'CLOSED'::text]))),
    CONSTRAINT travel_agent_accounts_type_check CHECK ((account_type = ANY (ARRAY['RECEIVABLE'::text, 'PAYABLE'::text, 'PREPAID'::text])))
);

CREATE TABLE IF NOT EXISTS travel_agent_contracts (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    hotel_id text NOT NULL,
    agent_id text NOT NULL,
    contract_code text NOT NULL,
    contract_name text NOT NULL,
    contract_type text NOT NULL,
    effective_from date NOT NULL,
    effective_to date NOT NULL,
    commission_basis text,
    commission_rate numeric,
    net_rate_applies boolean DEFAULT false,
    allotment_id integer,
    status text DEFAULT 'ACTIVE'::text NOT NULL,
    approved_by text,
    approved_at timestamp with time zone,
    created_by text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    notes text,
    version integer DEFAULT 1,
    parent_contract_id text,
    is_latest boolean DEFAULT true,
    superseded_at timestamp with time zone,
    CONSTRAINT travel_agent_contracts_date_check CHECK ((effective_to >= effective_from)),
    CONSTRAINT travel_agent_contracts_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'EXPIRED'::text, 'TERMINATED'::text]))),
    CONSTRAINT travel_agent_contracts_type_check CHECK ((contract_type = ANY (ARRAY['COMMISSION'::text, 'NET'::text, 'WHOLESALE'::text, 'ALLOTMENT'::text])))
);

CREATE TABLE IF NOT EXISTS travel_agent_statements (
    id text DEFAULT (gen_random_uuid())::text NOT NULL,
    hotel_id text NOT NULL,
    agent_id text NOT NULL,
    statement_code text NOT NULL,
    statement_date date NOT NULL,
    period_from date NOT NULL,
    period_to date NOT NULL,
    opening_balance numeric DEFAULT 0,
    total_charges numeric DEFAULT 0,
    total_payments numeric DEFAULT 0,
    closing_balance numeric DEFAULT 0,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    generated_by text,
    generated_at timestamp with time zone,
    sent_at timestamp with time zone,
    created_by text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    notes text,
    CONSTRAINT travel_agent_statements_date_check CHECK ((period_to >= period_from)),
    CONSTRAINT travel_agent_statements_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'GENERATED'::text, 'SENT'::text, 'PAID'::text, 'VOIDED'::text])))
);

